var i=`0171-risotto-ai-funghi`;var n=`world-0171`;var o=`IT`;var a=`southern-europe`;var r=4;var s=35;var g={en:`Risotto ai Funghi`,ua:`Грибне ризото`};var u={en:`A classic dish from Italy, featuring button mushroom, yellow onion, arborio rice, parmigiano reggiano. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: печериця, жовта цибуля, рис арборіо, парміджано реджано. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var m=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`button-mushroom`,420,`g`],[`yellow-onion`,115,`g`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Coat the rice in the warm fat with the aromatics and toast gently for about 3 minutes without browning.`,ua:`Змішайте рис із теплим жиром та ароматичними складниками й прогрівайте приблизно 3 хвилин, не підрум’янюючи.`,t:[`sauteing`,`risotto-method`],m:3,i:[[`arborio-rice`,320,`g`]]},{en:`Add hot stock gradually, one ladle at a time, stirring regularly for about 19 minutes until the rice is creamy yet firm in the center.`,ua:`Поступово вливайте гарячий бульйон по одному ополонику, регулярно помішуючи приблизно 19 хвилин, поки рис стане кремовим, але залишиться з легкою пружністю всередині.`,t:[`risotto-method`],m:19,i:[[`vegetable-stock`,1100,`ml`],[`dry-white-wine`,100,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parmigiano-reggiano`,85,`g`],[`unsalted-butter`,45,`g`],[`parsley`,20,`g`]]}];var l={slug:i,id:n,country:`IT`,region:a,servings:4,minutes:35,title:g,text:u,steps:m};export{o as country,l as default,n as id,s as minutes,a as region,r as servings,i as slug,m as steps,u as text,g as title};